//! The parser of the grammar language is generated by prpr from its own grammar. This checks
//! that the checked-in parser is what the current code generator, using that parser, generates.
//!
//! Run `PRPR_BLESS=1 cargo test -p prpr-cli --test bootstrap` to regenerate it.

use prpr_codegen::file::{Runtime, generate};
use std::path::Path;

#[test]
fn self_parser_is_up_to_date() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../prpr-codegen/src/parser");
    let grammar = std::fs::read_to_string(dir.join("prpr.peg")).unwrap();
    let generated = match generate(&grammar, &Runtime::Inline) {
        Ok(code) => code,
        Err(diags) => {
            let messages: Vec<String> = diags
                .iter()
                .map(|d| d.render(&grammar, "prpr.peg"))
                .collect();
            panic!("{}", messages.join("\n\n"));
        }
    };
    let path = dir.join("generated.rs");
    if std::env::var_os("PRPR_BLESS").is_some() {
        std::fs::write(&path, generated).unwrap();
        return;
    }
    let current = std::fs::read_to_string(&path).unwrap();
    assert!(
        current == generated,
        "{} is out of date; run `PRPR_BLESS=1 cargo test -p prpr-cli --test bootstrap`",
        path.display()
    );
}
